import { Link } from "@tanstack/react-router";
import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

/** Keeps every global filter (company, period, ...) when drilling down. */
export const keepSearch = ((p: Record<string, unknown>) => p) as never;
export const withSearch = (extra: Record<string, unknown>) =>
  ((p: Record<string, unknown>) => ({ ...p, ...extra })) as never;

export const fmtDate = (iso: string | null | undefined) =>
  iso ? iso.slice(0, 10).split("-").reverse().join("/") : "—";

export function pageHead(title: string, description: string) {
  return {
    meta: [
      { title: `${title} — BIOMIE` },
      { name: "description", content: description },
      { property: "og:title", content: `${title} — BIOMIE` },
      { property: "og:description", content: description },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  };
}

export function BackLink({ to, label }: { to: "/clientes" | "/produtos"; label: string }) {
  return (
    <Button asChild variant="ghost" size="sm" className="-ml-2 w-fit">
      <Link to={to} search={keepSearch}>
        <ArrowLeft className="size-4" /> {label}
      </Link>
    </Button>
  );
}

export function PageSkeleton() {
  return (
    <main className="mx-auto flex w-full max-w-[1400px] flex-col gap-4 px-4 py-8 md:px-6">
      <Skeleton className="h-10 w-64" />
      <Skeleton className="h-32" />
      <Skeleton className="h-80" />
    </main>
  );
}

export function Panel({
  title,
  actions,
  children,
}: {
  title: string;
  actions?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <section className="panel">
      <div className="flex flex-wrap items-center gap-2 border-b px-4 py-3">
        <h2 className="text-sm font-semibold">{title}</h2>
        <div className="ml-auto flex items-center gap-2">{actions}</div>
      </div>
      {children}
    </section>
  );
}

export const UNASSIGNED = "Não atribuído";

import { Link } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { Download } from "lucide-react";
import { toast } from "sonner";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { DataTable, type Column } from "@/components/analytics/DataTable";
import { fmtDate, keepSearch } from "@/components/entities/shared";
import { formatValue } from "@/domain/format";
import { share } from "@/domain/metrics/compute";
import {
  AGING_LABELS,
  TITLE_STATUS_LABELS,
  type AgingRow,
  type TitleStatus,
} from "@/domain/finance";
import { exportCsv, exportXlsx, type ExportColumn } from "@/lib/export";
import { authorizeFinanceExport } from "@/lib/finance.functions";
import type { TitleRow } from "@/lib/repositories/finance.repository.server";
import { cn } from "@/lib/utils";

const STATUS_CLASS: Record<TitleStatus, string> = {
  OPEN: "border-border text-foreground",
  PARTIALLY_PAID: "border-warning/40 text-warning",
  PAID: "border-success/40 text-success",
  OVERDUE: "border-destructive/40 text-destructive",
  CANCELLED: "border-border text-muted-foreground line-through",
};

export function StatusBadge({ status }: { status: TitleStatus }) {
  return (
    <Badge variant="outline" className={cn("font-normal", STATUS_CLASS[status])}>
      {TITLE_STATUS_LABELS[status]}
    </Badge>
  );
}

export function AgingTable({
  rows,
  overdueVisible,
}: {
  rows: AgingRow[];
  overdueVisible: boolean;
}) {
  const total = rows.reduce((a, r) => a + (r.value ?? 0), 0);
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b text-left text-xs text-muted-foreground">
            <th className="px-4 py-2 font-medium">Faixa</th>
            <th className="px-4 py-2 text-right font-medium">Valor</th>
            <th className="px-4 py-2 text-right font-medium">%</th>
            <th className="px-4 py-2 text-right font-medium">Títulos</th>
            <th className="px-4 py-2 text-right font-medium">Clientes</th>
            <th className="w-1/3 px-4 py-2" aria-hidden />
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const pct = r.value == null ? null : share(r.value, total);
            return (
              <tr key={r.bucket} className="border-b last:border-0">
                <td className="px-4 py-2">{AGING_LABELS[r.bucket]}</td>
                <td className="px-4 py-2 text-right tabular">{formatValue(r.value, "currency")}</td>
                <td className="px-4 py-2 text-right tabular">{formatValue(pct, "percent")}</td>
                <td className="px-4 py-2 text-right tabular">{formatValue(r.titles, "integer")}</td>
                <td className="px-4 py-2 text-right tabular">
                  {formatValue(r.customers, "integer")}
                </td>
                <td className="px-4 py-2">
                  <div className="h-2 rounded bg-muted">
                    <div
                      className={cn(
                        "h-2 rounded",
                        r.bucket === "future" ? "bg-primary" : "bg-destructive/70",
                      )}
                      style={{ width: `${Math.round((pct ?? 0) * 100)}%` }}
                    />
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {!overdueVisible && (
        <p className="px-4 py-3 text-xs text-muted-foreground">
          Faixas vencidas ocultas: seu perfil não tem a permissão de ver inadimplência.
        </p>
      )}
    </div>
  );
}

export function BilledVsReceivedChart({
  data,
}: {
  data: { month: string; billed: number; received: number }[];
}) {
  const points = data.map((d) => ({
    label: `${d.month.slice(5)}/${d.month.slice(2, 4)}`,
    Faturado: d.billed,
    Recebido: d.received,
  }));
  return (
    <div className="h-80 p-4">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={points} margin={{ left: 8, right: 8, top: 8 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
          <XAxis dataKey="label" tick={{ fontSize: 11 }} stroke="var(--muted-foreground)" />
          <YAxis
            tick={{ fontSize: 11 }}
            stroke="var(--muted-foreground)"
            width={70}
            tickFormatter={(v: number) => formatValue(v, "currency_compact")}
          />
          <Tooltip
            formatter={(v: number) => formatValue(v, "currency")}
            contentStyle={{
              background: "var(--popover)",
              border: "1px solid var(--border)",
              fontSize: 12,
            }}
          />
          <Legend wrapperStyle={{ fontSize: 12 }} />
          <Bar dataKey="Faturado" fill="var(--chart-2)" radius={[3, 3, 0, 0]} />
          <Bar dataKey="Recebido" fill="var(--chart-1)" radius={[3, 3, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

/** Export menu gated + audited server-side (finance.export). */
export function FinanceExportMenu<T>({
  company,
  kind,
  rows,
  columns,
  name,
  allowed,
}: {
  company: string;
  kind: string;
  rows: T[];
  columns: ExportColumn<T>[];
  name: string;
  allowed: boolean;
}) {
  const authorize = useServerFn(authorizeFinanceExport);
  if (!allowed) return null;
  const run = async (format: "csv" | "xlsx") => {
    try {
      await authorize({ data: { company, kind, rows: rows.length, format } });
      if (format === "csv") exportCsv(rows, columns, name);
      else await exportXlsx(rows, columns, name);
    } catch (e) {
      toast.error((e as Error).message);
    }
  };
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button size="sm" variant="outline" disabled={!rows.length}>
          <Download className="size-3.5" /> Exportar
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={() => void run("csv")}>CSV</DropdownMenuItem>
        <DropdownMenuItem onClick={() => void run("xlsx")}>Excel (XLSX)</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export const titleExportColumns = (withCustomer: boolean): ExportColumn<TitleRow>[] => [
  ...(withCustomer ? [{ header: "Cliente", value: (r: TitleRow) => r.customer }] : []),
  { header: "Documento", value: (r) => r.document },
  { header: "Parcela", value: (r) => `${r.installment}/${r.installments}` },
  { header: "Emissão", value: (r) => r.issueDate },
  { header: "Vencimento", value: (r) => r.dueDate },
  { header: "Liquidação", value: (r) => r.settledDate },
  { header: "Valor original", value: (r) => r.original },
  { header: "Ajustes (juros+multa−desconto)", value: (r) => r.adjustments },
  { header: "Pago", value: (r) => r.paid },
  { header: "Saldo", value: (r) => r.open },
  { header: "Dias de atraso", value: (r) => r.daysLate },
  { header: "Status", value: (r) => TITLE_STATUS_LABELS[r.status] },
  { header: "Vendedor", value: (r) => r.seller },
];

export function TitlesTable({
  rows,
  withCustomer,
  overdueVisible,
  toolbar,
}: {
  rows: TitleRow[];
  withCustomer: boolean;
  overdueVisible: boolean;
  toolbar?: React.ReactNode;
}) {
  const columns: Column<TitleRow>[] = [
    ...(withCustomer
      ? [
          {
            key: "customer",
            header: "Cliente",
            cell: (r: TitleRow) =>
              r.customerId ? (
                <Link
                  to="/clientes/$customerId"
                  params={{ customerId: r.customerId }}
                  search={keepSearch}
                  className="font-medium hover:underline"
                >
                  {r.customer}
                </Link>
              ) : (
                "—"
              ),
            sort: (r: TitleRow) => r.customer ?? "",
          },
        ]
      : []),
    { key: "doc", header: "Documento", cell: (r) => r.document, sort: (r) => r.document },
    {
      key: "inst",
      header: "Parcela",
      cell: (r) => `${r.installment}/${r.installments}`,
      sort: (r) => r.installment,
    },
    {
      key: "issue",
      header: "Emissão",
      cell: (r) => fmtDate(r.issueDate),
      sort: (r) => r.issueDate,
    },
    { key: "due", header: "Vencimento", cell: (r) => fmtDate(r.dueDate), sort: (r) => r.dueDate },
    {
      key: "settled",
      header: "Liquidação",
      cell: (r) => fmtDate(r.settledDate),
      sort: (r) => r.settledDate ?? "",
    },
    {
      key: "original",
      header: "Valor original",
      align: "right",
      cell: (r) => formatValue(r.original, "currency"),
      sort: (r) => r.original,
    },
    {
      key: "paid",
      header: "Pago",
      align: "right",
      cell: (r) => formatValue(r.paid, "currency"),
      sort: (r) => r.paid,
    },
    {
      key: "open",
      header: "Saldo",
      align: "right",
      cell: (r) => formatValue(r.open, "currency"),
      sort: (r) => r.open,
    },
    ...(overdueVisible
      ? [
          {
            key: "late",
            header: "Dias de atraso",
            align: "right" as const,
            cell: (r: TitleRow) => (
              <span className={r.status === "OVERDUE" ? "text-destructive" : undefined}>
                {r.daysLate ?? "—"}
              </span>
            ),
            sort: (r: TitleRow) => r.daysLate,
          },
        ]
      : []),
    {
      key: "status",
      header: "Status",
      cell: (r) => <StatusBadge status={r.status} />,
      sort: (r) => r.status,
    },
    {
      key: "seller",
      header: "Vendedor",
      cell: (r) => r.seller ?? "—",
      sort: (r) => r.seller ?? "",
    },
  ];
  return (
    <DataTable
      rows={rows}
      columns={columns}
      rowKey={(r) => r.id}
      search={(r) => `${r.customer ?? ""} ${r.document} ${r.seller ?? ""}`}
      toolbar={toolbar}
      initialSort={{ key: "due", dir: "desc" }}
    />
  );
}

import { Info } from "lucide-react";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Skeleton } from "@/components/ui/skeleton";
import { metric } from "@/domain/metrics/registry";
import { formatValue, type ValueFormat } from "@/domain/format";
import { STATUS_META, type FlightStatus } from "@/domain/flight-plan/config";
import { cn } from "@/lib/utils";

const TONE: Record<string, string> = {
  success: "text-success border-success/30 bg-success/10",
  warning: "text-warning-foreground border-warning/40 bg-warning/15 dark:text-warning",
  risk: "text-risk border-risk/30 bg-risk/10",
  destructive: "text-destructive border-destructive/30 bg-destructive/10",
};

/** Status communicates by symbol + text, not color only. */
export function StatusBadge({
  status,
  className,
}: {
  status: FlightStatus | null;
  className?: string;
}) {
  if (!status)
    return (
      <span
        className={cn(
          "inline-flex items-center rounded-md border px-1.5 py-0.5 text-[11px] text-muted-foreground",
          className,
        )}
      >
        — Sem avaliação
      </span>
    );
  const s = STATUS_META[status];
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 whitespace-nowrap rounded-md border px-1.5 py-0.5 text-[11px] font-medium",
        TONE[s.tone],
        className,
      )}
    >
      <span aria-hidden>{s.symbol}</span>
      {s.label}
    </span>
  );
}

interface FpKpiProps {
  metricKey: string;
  value: number | null;
  label?: string;
  format?: ValueFormat;
  sub?: React.ReactNode;
  emphasis?: boolean;
  tone?: "good" | "bad" | null;
}

export function FpKpi({ metricKey, value, label, format, sub, emphasis, tone }: FpKpiProps) {
  const def = metric(metricKey);
  return (
    <div className={cn("flex min-w-0 flex-col gap-1.5 p-4", emphasis && "md:p-5")}>
      <div className="flex items-center gap-1.5">
        <span className="eyebrow truncate">{label ?? def.name}</span>
        <Tooltip>
          <TooltipTrigger aria-label={`Sobre ${label ?? def.name}`}>
            <Info className="size-3 text-muted-foreground/70" />
          </TooltipTrigger>
          <TooltipContent className="max-w-xs">
            <p>{def.description}</p>
            <p className="mt-1 font-mono text-[10px] opacity-80">{def.formula}</p>
            {def.notes && <p className="mt-1 text-[11px] opacity-80">{def.notes}</p>}
          </TooltipContent>
        </Tooltip>
      </div>
      <div
        className={cn(
          "truncate font-semibold tracking-tight tabular",
          emphasis ? "text-xl md:text-2xl" : "text-lg",
          tone === "good" && "text-success",
          tone === "bad" && "text-destructive",
        )}
      >
        {formatValue(value, format ?? def.format)}
      </div>
      {sub && <div className="text-xs text-muted-foreground">{sub}</div>}
    </div>
  );
}

export function KpiGridSkeleton({ count }: { count: number }) {
  return (
    <>
      {Array.from({ length: count }, (_, i) => (
        <div key={i} className="flex flex-col gap-3 p-4">
          <Skeleton className="h-3 w-20" />
          <Skeleton className="h-6 w-28" />
        </div>
      ))}
    </>
  );
}

export const signTone = (v: number | null | undefined) =>
  v == null ? null : v >= 0 ? "good" : "bad";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { formatDelta, formatValue } from "@/domain/format";
import type { AnalyticsQuery } from "@/domain/filters";
import { salesBreakdownQuery } from "@/lib/queries";
import type { BreakdownRow, Dimension } from "@/lib/repositories/sales.repository.server";
import { DataTable, type Column } from "@/components/analytics/DataTable";
import { ExportMenu } from "@/components/analytics/ExportMenu";
import { exportName } from "@/lib/export";
import { cn } from "@/lib/utils";

export const DIM_LABELS: Record<Dimension, string> = {
  seller: "Vendedor",
  customer: "Cliente",
  product: "Produto",
  category: "Categoria",
  state: "Estado",
  city: "Cidade",
};

export function breakdownColumns(
  dim: Dimension,
  opts?: { lastDate?: boolean },
): Column<BreakdownRow>[] {
  const cols: Column<BreakdownRow>[] = [
    {
      key: "label",
      header: DIM_LABELS[dim],
      cell: (r) => (
        <div className="max-w-[260px] truncate">
          <span className="font-medium">{r.label ?? "Não atribuído"}</span>
          {r.sub && <span className="ml-2 text-xs text-muted-foreground">{r.sub}</span>}
        </div>
      ),
      sort: (r) => r.label ?? "",
    },
  ];
  if (dim === "product")
    cols.push({
      key: "category",
      header: "Categoria",
      cell: (r) => r.category,
      sort: (r) => r.category,
    });
  cols.push(
    {
      key: "revenue",
      header: "Faturamento",
      align: "right",
      cell: (r) => formatValue(r.revenue, "currency"),
      sort: (r) => r.revenue,
    },
    {
      key: "share",
      header: "Part.",
      align: "right",
      cell: (r) => formatValue(r.share, "percent"),
      sort: (r) => r.share,
    },
    {
      key: "variation",
      header: "Var. mês ant.",
      align: "right",
      cell: (r) => (
        <span
          className={cn(
            r.variation != null && (r.variation >= 0 ? "text-success" : "text-destructive"),
          )}
        >
          {formatDelta(r.variation)}
        </span>
      ),
      sort: (r) => r.variation,
    },
    {
      key: "units",
      header: "Qtd.",
      align: "right",
      cell: (r) => formatValue(r.units, "integer"),
      sort: (r) => r.units,
    },
    {
      key: "invoices",
      header: "NFs",
      align: "right",
      cell: (r) => formatValue(r.invoices, "integer"),
      sort: (r) => r.invoices,
    },
  );
  if (dim !== "product" && dim !== "category")
    cols.push({
      key: "ticket",
      header: "Ticket",
      align: "right",
      cell: (r) => formatValue(r.ticket, "currency"),
      sort: (r) => r.ticket,
    });
  if (opts?.lastDate)
    cols.push({
      key: "lastDate",
      header: "Última compra",
      align: "right",
      cell: (r) => (r.lastDate ? r.lastDate.split("-").reverse().join("/") : "—"),
      sort: (r) => r.lastDate,
    });
  return cols;
}

export const breakdownExport = (dim: Dimension) => [
  { header: DIM_LABELS[dim], value: (r: BreakdownRow) => r.label },
  { header: "Detalhe", value: (r: BreakdownRow) => r.sub },
  { header: "Categoria", value: (r: BreakdownRow) => r.category },
  { header: "Faturamento", value: (r: BreakdownRow) => r.revenue },
  { header: "Participação", value: (r: BreakdownRow) => r.share },
  { header: "Faturamento mês anterior", value: (r: BreakdownRow) => r.previous },
  { header: "Variação", value: (r: BreakdownRow) => r.variation },
  { header: "Quantidade", value: (r: BreakdownRow) => r.units },
  { header: "NFs", value: (r: BreakdownRow) => r.invoices },
  { header: "Ticket", value: (r: BreakdownRow) => r.ticket },
];

export function SalesDrivers({
  q,
  dim,
  onDim,
}: {
  q: AnalyticsQuery;
  dim: Dimension;
  onDim: (d: Dimension) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const { data, isPending, error } = useQuery(salesBreakdownQuery(q, dim));
  const rows = data?.rows ?? [];
  return (
    <section className="panel">
      <div className="flex flex-wrap items-center gap-3 border-b px-4 py-3">
        <h2 className="text-sm font-semibold">Drivers do resultado</h2>
        <Tabs
          className="min-w-0 max-w-full"
          value={dim}
          onValueChange={(v) => onDim(v as Dimension)}
        >
          <TabsList className="h-8 max-w-full justify-start overflow-x-auto">
            {(Object.keys(DIM_LABELS) as Dimension[]).map((d) => (
              <TabsTrigger key={d} value={d} className="text-xs">
                Por {DIM_LABELS[d]}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
        <div className="ml-auto">
          <ExportMenu
            rows={rows}
            columns={breakdownExport(dim)}
            name={exportName(`vendas-por-${dim}`, q)}
          />
        </div>
      </div>
      {error ? (
        <p className="p-6 text-sm text-muted-foreground">{error.message}</p>
      ) : isPending ? (
        <Skeleton className="m-4 h-48" />
      ) : (
        <>
          <DataTable
            rows={expanded ? rows : rows.slice(0, 10)}
            columns={breakdownColumns(dim)}
            rowKey={(r, i) => r.key ?? `none-${i}`}
            {...(expanded ? { search: (r: BreakdownRow) => `${r.label} ${r.sub ?? ""}` } : {})}
            pageSize={200}
          />
          {rows.length > 10 && (
            <div className="border-t p-2 text-center">
              <Button size="sm" variant="ghost" onClick={() => setExpanded((e) => !e)}>
                {expanded ? "Mostrar top 10" : `Ver tabela completa (${rows.length})`}
              </Button>
            </div>
          )}
        </>
      )}
    </section>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
